#nullable enable
using System.Reflection; using Modular.Modules.Contracts;
namespace Modular.Modules.ModuleManagement.Application;
public sealed class ModuleManagementService { readonly IModuleCatalog catalog; readonly ModuleManagementValidator validator; public ModuleManagementService(IModuleCatalog c,ModuleManagementValidator v)=>(catalog,validator)=(c,v); public IReadOnlyCollection<ModuleRecord> List()=>catalog.List(); public ModuleRecord? Get(string id)=>catalog.Find(id); public IReadOnlyCollection<ModuleDescriptor> Discover(Assembly a)=>ModuleDiscovery.Discover(a).ToArray(); public ServiceResult<ModuleRecord> Save(ModuleInput x){var v=validator.Validate(x);if(!v.IsValid)return ServiceResult<ModuleRecord>.Invalid(v.Errors);var old=catalog.Find(x.Id);var m=new ModuleRecord(x.Id.Trim(),x.Name.Trim(),x.Version.Trim(),x.Description?.Trim()??string.Empty,x.Kind,old?.Status??ModuleStatus.Disabled,old?.IsDiscovered??false,x.Dependencies.Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),DateTimeOffset.UtcNow);return ServiceResult<ModuleRecord>.Success(catalog.Upsert(m));} public ServiceResult<ModuleRecord> SetEnabled(string id,bool enabled){var old=catalog.Find(id);if(old is null)return ServiceResult<ModuleRecord>.Invalid(new[]{"Module was not found."});if(enabled&&old.Dependencies.Any(d=>catalog.Find(d)?.Status!=ModuleStatus.Enabled))return ServiceResult<ModuleRecord>.Invalid(new[]{"All module dependencies must be enabled first."});return ServiceResult<ModuleRecord>.Success(catalog.Upsert(old with{Status=enabled?ModuleStatus.Enabled:ModuleStatus.Disabled,LastChangedUtc=DateTimeOffset.UtcNow}));} public bool Delete(string id)=>catalog.Remove(id); }
public sealed record ServiceResult<T>(T? Value,IReadOnlyCollection<string> Errors){public bool Succeeded=>Errors.Count==0&&Value is not null;public static ServiceResult<T> Success(T x)=>new(x,Array.Empty<string>());public static ServiceResult<T> Invalid(IEnumerable<string> e)=>new(default,e.ToArray());}
